// Follow a direct event URL while preserving the existing workspace routes.
function routeTopic() {
  return location.hash.startsWith("#collaboration/")
    ? location.hash.split("/")[1]
    : "";
}

// Home cards summarize actual pending events instead of teaching the collaboration mechanism.
export function CollaborationSummary({
  state,
  mobile = false,
  onOpen,
}: {
  state: MobileState;
  mobile?: boolean;
  onOpen: () => void;
}) {
  const active = topics.filter(
    (t) => caseWorkflow(state, t.id).phase !== "completed",
  );
  const pending = active.filter(
    (t) =>
      collaborationTask(state, t.id).owner === (mobile ? "App 端" : "网页端"),
  );
  return (
    <button
      className={`co-summary ${mobile ? "is-mobile" : ""}`}
      onClick={onOpen}
    >
      <span className="co-summary-icon">
        <ListChecks size={22} />
      </span>
      <span className="co-summary-copy">
        <small>事件处置</small>
        <strong>{pending.length} 项待处理事项</strong>
        <span>在办事件 {active.length} 项 · 查看核验与审批进展</span>
      </span>
      <ArrowRight size={18} />
    </button>
  );
}

